function getDistance(x1, y1, x2, y2) { return Math.hypot(x2 - x1, y2 - y1); }
function rectanguloColisiona(r1, r2) { return !(r1.x + r1.w < r2.x || r1.x > r2.x + r2.w || r1.y + r1.h < r2.y || r1.y > r2.y + r2.h); }

function getPlayerDefenseFisica(playerId) { const j = players[playerId]; if (!j) return 0; const inv = inventariosJugadores[playerId]; let def = 0; let claseKey = (j.className || j.class || 'warrior').toLowerCase(); if (claseKey.includes('mago')) claseKey = 'mago'; if (claseKey.includes('necromancer')) claseKey = 'necromancer'; const statsBase = CONFIG.PLAYER.BASE_STATS[claseKey] || CONFIG.PLAYER.BASE_STATS.warrior; def += (statsBase.defensaFisica || 0); if (inv && inv.items) { const cabezaId = j.equipamiento?.cabeza; if (cabezaId) { const item = inv.items.find(i => i.id === cabezaId); if (item && item.defensaFisica) def += Math.floor(item.defensaFisica); } const pechoId = j.equipamiento?.pecho; if (pechoId) { const item = inv.items.find(i => i.id === pechoId); if (item && item.defensaFisica) def += Math.floor(item.defensaFisica); } const armaduraId = j.equipamiento?.armadura; if (armaduraId) { const item = inv.items.find(i => i.id === armaduraId); if (item && item.defensaFisica) def += Math.floor(item.defensaFisica); } const piernasId = j.equipamiento?.piernas; if (piernasId) { const item = inv.items.find(i => i.id === piernasId); if (item && item.defensaFisica) def += Math.floor(item.defensaFisica); } const piesId = j.equipamiento?.pies; if (piesId) { const item = inv.items.find(i => i.id === piesId); if (item && item.defensaFisica) def += Math.floor(item.defensaFisica); } const escudoId = j.equipamiento?.escudo; if (escudoId) { const item = inv.items.find(i => i.id === escudoId); if (item && item.defensaFisica) def += Math.floor(item.defensaFisica); } } return Math.max(0, Math.floor(def)); }

function getPlayerDefensaMagica(playerId) { const j = players[playerId]; if (!j) return 0; const inv = inventariosJugadores[playerId]; let def = 0; let claseKey = (j.className || j.class || 'warrior').toLowerCase(); if (claseKey.includes('mago')) claseKey = 'mago'; if (claseKey.includes('necromancer')) claseKey = 'necromancer'; const statsBase = CONFIG.PLAYER.BASE_STATS[claseKey] || CONFIG.PLAYER.BASE_STATS.warrior; def += (statsBase.defensaMagica || 0); def += Math.floor((j.stats?.inteligencia || 0) / 2); if (inv && inv.items) { const cabezaId = j.equipamiento?.cabeza; if (cabezaId) { const item = inv.items.find(i => i.id === cabezaId); if (item && item.defensaMagica) def += Math.floor(item.defensaMagica); } const pechoId = j.equipamiento?.pecho; if (pechoId) { const item = inv.items.find(i => i.id === pechoId); if (item && item.defensaMagica) def += Math.floor(item.defensaMagica); } const armaduraId = j.equipamiento?.armadura; if (armaduraId) { const item = inv.items.find(i => i.id === armaduraId); if (item && item.defensaMagica) def += Math.floor(item.defensaMagica); } const piernasId = j.equipamiento?.piernas; if (piernasId) { const item = inv.items.find(i => i.id === piernasId); if (item && item.defensaMagica) def += Math.floor(item.defensaMagica); } const piesId = j.equipamiento?.pies; if (piesId) { const item = inv.items.find(i => i.id === piesId); if (item && item.defensaMagica) def += Math.floor(item.defensaMagica); } const escudoId = j.equipamiento?.escudo; if (escudoId) { const item = inv.items.find(i => i.id === escudoId); if (item && item.defensaMagica) def += Math.floor(item.defensaMagica); } } return Math.max(0, Math.floor(def)); }

function calcularPoderJugador(playerId) { const j = players[playerId]; if (!j) return 0; let ataqueFisico = j.ataqueFisico || 0; let ataqueMagico = 0; let defensaFisica = getPlayerDefenseFisica(playerId); let defensaMagica = getPlayerDefensaMagica(playerId); let hpMax = j.maxHp || 500; let manaMax = j.maxMana || 100; let velocidad = 150; let claseKey = (j.className || j.class || 'warrior').toLowerCase(); if (claseKey.includes('mago')) claseKey = 'mago'; if (claseKey.includes('necromancer')) claseKey = 'necromancer'; const statsBase = CONFIG.PLAYER.BASE_STATS[claseKey] || CONFIG.PLAYER.BASE_STATS.warrior; velocidad = statsBase.velocidad || 150; const inv = inventariosJugadores[playerId]; if (inv) { const armaId = j.equipamiento?.arma; if (armaId) { const arma = inv.items.find(i => i.id === armaId); if (arma) { ataqueFisico += arma.ataqueFisico || 0; ataqueMagico += arma.ataqueMagico || 0; velocidad += arma.velocidad || 0; if (arma.dañoFuego) ataqueMagico += arma.dañoFuego; if (arma.dañoLuz) ataqueMagico += arma.dañoLuz; if (arma.manaBonus) manaMax += arma.manaBonus; } } const escudoId = j.equipamiento?.escudo; if (escudoId) { const escudo = inv.items.find(i => i.id === escudoId); if (escudo) { defensaFisica += escudo.defensaFisica || 0; defensaMagica += escudo.defensaMagica || 0; velocidad += escudo.velocidad || 0; } } const armaduraId = j.equipamiento?.armadura; if (armaduraId) { const armadura = inv.items.find(i => i.id === armaduraId); if (armadura) { defensaFisica += armadura.defensaFisica || 0; defensaMagica += armadura.defensaMagica || 0; velocidad += armadura.velocidad || 0; } } } if (j.stats) { ataqueFisico += (j.stats.fuerza || 0) * 1.5; ataqueMagico += (j.stats.inteligencia || 0) * 1.5; hpMax += (j.stats.vitalidad || 0) * 10; manaMax += (j.stats.sabiduria || 0) * 10; velocidad += (j.stats.agilidad || 0) * 1.5; } const nivel = j.level || 1; const poder = Math.floor((ataqueFisico * 2) + (ataqueMagico * 2) + (defensaFisica * 1.5) + (defensaMagica * 1.5) + (hpMax * 0.5) + (manaMax * 0.2) + (velocidad * 0.3) + (nivel * 10)); return Math.max(1, poder); }

function obtenerTop10() { const ranking = []; for (let id in players) { const j = players[id]; if (j && j.isAlive !== false) { ranking.push({ id: id, nombre: j.name, clase: j.className, nivel: j.level || 1, poder: calcularPoderJugador(id) }); } } ranking.sort((a, b) => b.poder - a.poder); return ranking.slice(0, 10); }

function calcularDañoFinal(objetivoId, dañoBase, tipo = 'fisico', elemento = null) { const j = players[objetivoId]; if (!j) return Math.max(1, Math.floor(dañoBase)); let daño = Math.floor(dañoBase); if (objetivoId && players[objetivoId] && (players[objetivoId].className || '').toUpperCase() === 'CABALLERO' && sacrificioActivoServer[objetivoId] && (players[objetivoId].stats?.sacrificio || 0) > 0 && !playerTeam[objetivoId]) { const absorbido = Math.floor(daño * 0.15); if (absorbido > 0) { daño = Math.max(0, daño - absorbido); } } const tid = playerTeam[objetivoId]; if (tid && teams[tid]) { const team = teams[tid]; let caballeroCercano = null; let menorDistancia = Infinity; team.miembros.forEach(m => { if (m !== objetivoId && players[m] && players[m].className === 'CABALLERO' && players[m].isAlive) { const cab = players[m]; if (cab.stats && cab.stats.sacrificio > 0 && sacrificioActivoServer[cab.id]) { const rango = 50 + ((cab.stats.sacrificio || 0) * 2); const dist = getDistance(j.x, j.y, cab.x, cab.y); if (dist < rango && dist < menorDistancia) { menorDistancia = dist; caballeroCercano = cab; } } } }); if (caballeroCercano) { const porcentajeAbsorcion = 0.15 + ((caballeroCercano.stats.sacrificio || 0) * 0.005); const dañoAbsorbido = Math.floor(daño * porcentajeAbsorcion); if (dañoAbsorbido > 0) { caballeroCercano.hp = Math.max(0, caballeroCercano.hp - dañoAbsorbido); daño = Math.max(0, daño - dañoAbsorbido); io.emit('playerStatsUpdate', { id: caballeroCercano.id, hp: caballeroCercano.hp }); io.to(caballeroCercano.id).emit('chatMessage', { type: 'system', name: 'Sistema', msg: `Sacrificio: absorbiste ${dañoAbsorbido} de daño` }); io.to(objetivoId).emit('chatMessage', { type: 'system', name: 'Sistema', msg: `${caballeroCercano.name} absorbio ${dañoAbsorbido} de daño por ti` }); } } } let defensa = 0; if (tipo === 'fisico') { defensa = Math.floor(getPlayerDefenseFisica(objetivoId)); } else if (tipo === 'magico' && elemento) { switch(elemento) { case 'fuego': defensa = Math.floor(j?.stats?.defFuego || 0); break; case 'agua': defensa = Math.floor(j?.stats?.defAgua || 0); break; case 'viento': defensa = Math.floor(j?.stats?.defViento || 0); break; case 'rayo': defensa = Math.floor(j?.stats?.defRayo || 0); break; case 'luz': defensa = Math.floor(j?.stats?.defLuz || 0); break; case 'oscuridad': defensa = Math.floor(j?.stats?.defOscuridad || 0); break; default: defensa = 0; } } else if (tipo === 'magico') { defensa = Math.floor(getPlayerDefensaMagica(objetivoId)); } if (defensa < 0) defensa = 0; let dañoFinal = Math.max(0, Math.floor(daño - defensa)); return dañoFinal; }

function darExpAJugadorYEquipo(socketId, exp) { const j = players[socketId]; if (!j) return; if (j.level === undefined || j.level === null || isNaN(j.level)) j.level = 1; if (j.exp === undefined || j.exp === null || isNaN(j.exp)) j.exp = 0; if (!j.stats) j.stats = {}; if (j.stats.puntosDisponibles === undefined || j.stats.puntosDisponibles === null || isNaN(j.stats.puntosDisponibles)) j.stats.puntosDisponibles = 5; if (j.stats.puntosEspecialidad === undefined || j.stats.puntosEspecialidad === null || isNaN(j.stats.puntosEspecialidad)) j.stats.puntosEspecialidad = 0; j.exp += exp; const expNecesaria = j.level * 100; while (j.exp >= expNecesaria) { j.exp -= expNecesaria; j.level += 1; j.stats.puntosDisponibles += 3; j.stats.puntosEspecialidad += 1; io.to(socketId).emit('chatMessage', { type: 'system', name: 'Sistema', msg: `🎉 ¡Has subido al nivel ${j.level}! (+3 puntos, +1 especialidad)` }); } io.to(socketId).emit('playerExpGain', { id: socketId, exp: exp, totalExp: j.exp, level: j.level, expNecesaria: j.level * 100, puntosDisponibles: j.stats.puntosDisponibles, puntosEspecialidad: j.stats.puntosEspecialidad }); const t = playerTeam[socketId]; if (t && teams[t]) { teams[t].miembros.forEach(m => { if (m !== socketId && players[m]) { if (players[m].exp === undefined || players[m].exp === null || isNaN(players[m].exp)) players[m].exp = 0; players[m].exp += exp; io.to(m).emit('playerExpGain', { id: m, exp: exp }); } }); } }

function revivirJugador(socketId) { const j = players[socketId]; if (!j) return; j.isAlive = true; j.hp = j.maxHp || CONFIG.PLAYER.MAX_HP; j.mana = (CONFIG.PLAYER.BASE_STATS[j.class]?.mana || 100); j.x = 512; j.y = 470; jugadoresEnMapa[socketId] = 'principal'; io.emit('playerRespawn', { id: socketId, x: 512, y: 512 }); }
function cambiarJugadorDeMapa(socketId, mapa) { if (!players[socketId]) return; jugadoresEnMapa[socketId] = mapa; players[socketId].mapa = mapa; io.to(socketId).emit('cambioMapa', { mapa: mapa }); actualizarVisibilidadJugadores(socketId); }
function actualizarVisibilidadJugadores(socketId) { const jugador = players[socketId]; if (!jugador) return; const miMapa = jugadoresEnMapa[socketId] || 'principal'; const jugadoresMismoMapa = {}; for (let id in players) { if (id !== socketId && players[id] && (jugadoresEnMapa[id] || 'principal') === miMapa) { jugadoresMismoMapa[id] = players[id]; } } io.to(socketId).emit('currentPlayers', jugadoresMismoMapa); for (let id in players) { if (id !== socketId && players[id] && (jugadoresEnMapa[id] || 'principal') === miMapa) { io.to(id).emit('newPlayer', players[socketId]); } } }

